export function BlockArt({ id, size = 104 }) {
  const d = ART[id];
  if (!d) return <span style={{ width: size, height: size }} />;
  return (
    <svg viewBox="0 0 120 120" width={size} height={size} aria-hidden="true">
      <path d={d} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}
